// ***************
// Filename: spi_flash_ctrl_top.sv
// Author: FPGA Cores 4 U
// Description: spi_flash_ctrl with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   spi_flash_ctrl_regs (u_regs, src/include/spi_flash_ctrl_regs.sv, ID
//   "SPFL", VERSION and DATE at 0x00-0x08, the registers from 0x10) and the
//   logic spi_flash_ctrl (u_core, src/spi_flash_ctrl.sv), joined by the
//   register interface spi_flash_ctrl_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from spi_flash_ctrl_regs.json and the ports of
//   spi_flash_ctrl: regenerate after changing either. Clock - aclk. Reset -
//   synchronous active low aresetn.
// Date: 2026-10-20
module spi_flash_ctrl_top (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.slave s_axis,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = 8
  axis_if.master m_axis,
  // spi: spi_if.master (ip/shared/src/interfaces/spi_if.sv), NUM_CS = 1 {sclk_o=sclk mosi_o=mosi miso_i=miso cs_n_o=cs_n}
  spi_if.master spi,
  output logic irq_o
);
  // register interface between the register map and the logic
  spi_flash_ctrl_regs_if u_regs_if ();

  spi_flash_ctrl_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  spi_flash_ctrl u_core (
    .aclk,
    .aresetn,
    .s_axis,
    .m_axis,
    .spi,
    .irq_o,
    .regs(u_regs_if)
  );
endmodule
